
import codecs
from django.db import models


class Transaction(models.Model):
    """
    'txid': '04b11c78906d6cf94792cabe03c542c47626dae7521c007f2d7eecd10944ab40',
    'amount': 0.01,
    'amountZat': 1000000,
    'memo': '',
    'outindex': 0,
    'confirmations': 2559,
    'blockheight': 1591145,
    'blockindex': 5,
    'blocktime': 1646783796,
    'change': False
    """
    created_at = models.DateTimeField(auto_now_add=True)
    zpage = models.ForeignKey(
        'g12f.zPage', on_delete=models.PROTECT, null=True, blank=True)
    creator = models.ForeignKey(
        'g12f.Creator', on_delete=models.PROTECT, null=True, blank=True
    )
    action = models.CharField(max_length=64)

    # TODO: breathing room UA upgrade?
    txid = models.CharField(max_length=64, primary_key=True)
    amount = models.DecimalField(
        decimal_places=8, max_digits=10,
        # TODO: only positive?
    )
    memo = models.TextField(blank=True)
    memo_plain = models.TextField(blank=True)

    # Can add others later
    #

    class Meta:
        ordering = ['-created_at']

    def __str__(self) -> str:
        return self.txid

    @property
    def ascii_memo(self) -> str:
        try:
            s = codecs.decode(self.memo, 'hex').decode()
            s = s.replace('\x00', '')
            return s
        except:
            return ""
